import{_ as r,c as o,o as i,a5 as a}from"./chunks/framework.CUJoMJm2.js";const h=JSON.parse('{"title":"RPC Behavior","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/rpc/behavior.md","filePath":"protocols/rpc/behavior.md","lastUpdated":0}'),t={name:"protocols/rpc/behavior.md"};function n(s,e,c,l,d,p){return i(),o("div",null,[...e[0]||(e[0]=[a('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /protocols/rpc/behavior.md for this page in Markdown format</div><h1 id="rpc-behavior" tabindex="-1">RPC Behavior <a class="header-anchor" href="#rpc-behavior" aria-label="Permalink to “RPC Behavior”">​</a></h1><blockquote><p><strong>Authority</strong>: Primary (Normative)<br><strong>Purpose</strong>: Request/response semantics, timeouts, correlation, and retry guidance.</p></blockquote><h2 id="request-response-lifecycle" tabindex="-1">Request/Response Lifecycle <a class="header-anchor" href="#request-response-lifecycle" aria-label="Permalink to “Request/Response Lifecycle”">​</a></h2><ol><li>Client sends <code>RpcRequest</code> with unique <code>cid</code> (correlation ID)</li><li>Server processes request</li><li>Server sends <code>RpcSuccess</code> or <code>RpcError</code> with matching <code>cid</code></li></ol><h2 id="correlation" tabindex="-1">Correlation <a class="header-anchor" href="#correlation" aria-label="Permalink to “Correlation”">​</a></h2><p>RPC correlation uses <code>cid</code> (correlation ID), not SBP <code>frameId</code>:</p><ul><li><code>cid</code> in requests is the sending frame&#39;s <code>frameId</code></li><li><code>cid</code> in responses matches the original request&#39;s <code>cid</code></li><li>Runtime matches on <code>cid</code>, not <code>frameId</code></li></ul><p>This enables relays, proxies, and fan-out without wire format changes. See ADR-010.</p><h2 id="timeouts" tabindex="-1">Timeouts <a class="header-anchor" href="#timeouts" aria-label="Permalink to “Timeouts”">​</a></h2><p>Implementations SHOULD:</p><ul><li>Set request timeout of 30 seconds by default</li><li>Allow per-method timeout configuration</li><li>Return <code>RpcError</code> with code 1103 (Timeout) on expiry</li></ul><p>Implementations MUST:</p><ul><li>Not assume responses arrive in request order</li><li>Handle responses after timeout gracefully (discard)</li></ul><p><strong>Key invariant</strong>: Routers MUST NOT use SBP <code>ErrorFrame</code> to represent handler timeouts. Timeouts MUST be delivered as <code>RpcError</code> responses (code 1103).</p><h2 id="retry-guidance" tabindex="-1">Retry Guidance <a class="header-anchor" href="#retry-guidance" aria-label="Permalink to “Retry Guidance”">​</a></h2><p>Implementations MAY retry failed requests:</p><ul><li>On transport errors (not on application errors)</li><li>With exponential backoff (recommended: 1s, 2s, 4s, max 30s)</li><li>With jitter to avoid thundering herd</li></ul><p>Implementations MUST NOT retry:</p><ul><li>After receiving <code>RpcError</code> (server explicitly rejected)</li><li>Without new <code>cid</code> (would confuse correlation)</li></ul><h2 id="concurrent-requests" tabindex="-1">Concurrent Requests <a class="header-anchor" href="#concurrent-requests" aria-label="Permalink to “Concurrent Requests”">​</a></h2><p>Multiple requests MAY be in flight simultaneously:</p><ul><li>Each request has unique <code>cid</code></li><li>Responses may arrive out of order</li><li>Implementations SHOULD track pending requests by <code>cid</code></li></ul><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to “Notifications”">​</a></h2><p><code>RpcNotification</code> (<code>t:&quot;N&quot;</code>) is fire-and-forget:</p><ul><li>MUST use <code>event/</code> subjects (see <a href="./envelope#subject-namespacing">envelope.md</a>)</li><li>No <code>cid</code> (no correlation)</li><li>No response expected</li><li>No delivery guarantee beyond transport layer</li></ul><h2 id="transport-semantics" tabindex="-1">Transport Semantics <a class="header-anchor" href="#transport-semantics" aria-label="Permalink to “Transport Semantics”">​</a></h2><p>RpcError is request-scoped and MUST NOT trigger transport close.</p><h2 id="invalid-envelope-handling" tabindex="-1">Invalid Envelope Handling <a class="header-anchor" href="#invalid-envelope-handling" aria-label="Permalink to “Invalid Envelope Handling”">​</a></h2><p>Error handling differs by subject prefix to prevent amplification attacks while preserving diagnostics.</p><h3 id="for-rpc-subjects" tabindex="-1">For <code>rpc/*</code> Subjects <a class="header-anchor" href="#for-rpc-subjects" aria-label="Permalink to “For rpc/* Subjects”">​</a></h3><ul><li>If envelope is invalid <strong>but <code>cid</code> is extractable</strong>: respond with <code>RpcError{code: 1100, cid, message}</code></li><li>If envelope is invalid <strong>and <code>cid</code> is not extractable</strong>: emit <code>ErrorFrame{code: 1002}</code> and continue (non-fatal)</li><li>MUST NOT close connection for a single invalid envelope</li></ul><h3 id="for-event-subjects" tabindex="-1">For <code>event/*</code> Subjects <a class="header-anchor" href="#for-event-subjects" aria-label="Permalink to “For event/* Subjects”">​</a></h3><ul><li>If envelope is invalid: MUST drop</li><li>MAY log (rate-limited to prevent log DoS)</li><li>MUST NOT emit <code>ErrorFrame</code> (prevents attacker-triggered error storms)</li></ul><p>Rationale: Events are fire-and-forget with no reply channel. Emitting <code>ErrorFrame</code> for malformed events would allow attackers to amplify traffic.</p>',35)])])}const m=r(t,[["render",n]]);export{h as __pageData,m as default};
